WITH checks AS (SELECT 'rpc_exists' AS check_name,to_regprocedure('public.admin_deactivate_customers_v1(uuid[])') IS NOT NULL AS ok UNION ALL SELECT 'hard_delete_guard_exists',EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.customers'::regclass AND tgname='trg_customers_block_hard_delete_v1' AND NOT tgisinternal) UNION ALL SELECT 'audit_table_exists',to_regclass('public.customer_deactivation_audit') IS NOT NULL UNION ALL SELECT 'anon_cannot_execute',NOT has_function_privilege('anon','public.admin_deactivate_customers_v1(uuid[])','EXECUTE') UNION ALL SELECT 'authenticated_can_execute',has_function_privilege('authenticated','public.admin_deactivate_customers_v1(uuid[])','EXECUTE')) SELECT check_name,ok FROM checks WHERE NOT ok ORDER BY check_name;
